    ['REQUIRED_EXPECTED_SIGNALS', hasMarker(text, labelMarker('expected signals|expected')) || hasMarker(text, /^#{2,4}\s+Expected(?: Signals)?\b/im) || tableFieldPresent(table, 'expected signals'), 'expected signals are missing'],
